<?php

$edit=null;if(isset($query['edit'])){$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([(int)$query['edit']]);$edit=$s->fetch();}
$roles=$db->query('SELECT * FROM roles ORDER BY name')->fetchAll();
$employees=$db->query("SELECT id,employee_no,first_name,last_name FROM employees WHERE archived_at IS NULL ORDER BY last_name,first_name")->fetchAll();
echo '<div class="form-card"><h3>'.($edit?'Edit User':'Create User').'</h3><form method="post">'.csrf_field().'<input type="hidden" name="action" value="save"><input type="hidden" name="id" value="'.e($edit['id']??'').'"><div class="form-grid"><div class="form-group"><label>Name</label><input name="name" required value="'.e($edit['name']??'').'"></div><div class="form-group"><label>Email</label><input type="email" name="email" required value="'.e($edit['email']??'').'"></div><div class="form-group"><label>Role</label><select name="role_id">';foreach($roles as $r)echo '<option value="'.$r['id'].'"'.selected($edit['role_id']??'', $r['id']).'>'.e($r['name']).'</option>';echo '</select></div><div class="form-group"><label>Employee Link</label><select name="employee_id"><option value="">No employee link</option>';foreach($employees as $e)echo '<option value="'.$e['id'].'"'.selected($edit['employee_id']??'', $e['id']).'>'.e($e['employee_no'].' · '.$e['last_name'].', '.$e['first_name']).'</option>';echo '</select></div><div class="form-group"><label>Status</label><select name="status"><option value="active"'.selected($edit['status']??'active','active').'>Active</option><option value="inactive"'.selected($edit['status']??'active','inactive').'>Inactive</option></select></div><div class="form-group"><label>'.($edit?'New Password (leave blank to keep current)':'Temporary Password').'</label><input type="password" name="password" '.($edit?'':'required').'><span class="help">Minimum 8 characters. Temporary credentials should be changed before production use.</span></div></div><div class="actions" style="margin-top:12px"><button class="btn btn-primary">'.($edit?'Save User':'Create User').'</button>'.($edit?'<a class="btn btn-secondary" href="?page=users">Cancel</a>':'').'</div></form></div>';

$rows=$db->query('SELECT u.*,r.name role_name,e.employee_no FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN employees e ON e.id=u.employee_id ORDER BY u.name')->fetchAll();
echo '<div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Employee Link</th><th>Status</th><th>Last Login</th><th></th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['email']).'</td><td>'.e($r['role_name']).'</td><td>'.e($r['employee_no']?:'—').'</td><td>'.badge($r['status'],$r['status']==='active'?'good':'neutral').'</td><td>'.e($r['last_login_at']?:'Never').'</td><td><a class="btn btn-secondary" href="?page=users&edit='.$r['id'].'">Edit</a></td></tr>';echo '</tbody></table></div>';

